import express from 'express';
import {once} from 'node:events';
import type {AddressInfo} from 'node:net';
import {MongoClient} from 'mongodb';
import {WebSocket} from 'ws';
import {createServer, type HalServerOptions} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {validateMessage} from './ws/validation.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {MongoSessionStore} from '../infrastructure/stores/mongo/mongoSessionStore.js';
import type {MongoSessionDocument} from '../infrastructure/stores/mongo/mongoSessionDocument.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {createChatOrchestrator, type OrchestratorHooks} from '../orchestration/chatOrchestrator.js';
import {createBedrockProvider} from '../providers/bedrock/bedrockProvider.js';
import type {SessionListOptions, SessionStore} from '../types/sessionStore.js';
import {captureErrors} from '../shared/logCaptureTestSupport.js';

interface Row {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}
interface Frame {
  type: string;
  code?: string;
  message?: string;
  sessionId?: string;
  resumed?: boolean;
  conversations?: Row[];
  entry?: {content?: string};
}

const servers: Array<ReturnType<typeof createServer>> = [];
const sockets: WebSocket[] = [];
const errors = captureErrors();

afterEach(async () => {
  for (const socket of sockets.splice(0)) socket.terminate();
  for (const server of servers.splice(0)) await server.stop();
});

// Records actual calls and delegates to the shipped store; it never supplies canned results.
class RecordedStore extends InMemorySessionStore {
  readonly calls: Array<{userId: string | number; options?: SessionListOptions}> = [];
  override listFor(userId: string | number, options?: SessionListOptions) {
    this.calls.push({userId, options});
    return super.listFor(userId, options);
  }
}

async function start(sessionStore: SessionStore, history?: {enabled: boolean}, hooks?: OrchestratorHooks) {
  const options: HalServerOptions & {history?: {enabled: boolean}} = {
    app: express(),
    wsAuth: async () => ({id: 'owner'}),
    sessionStore,
    resume: {enabled: true},
    history,
    orchestrator: createChatOrchestrator(
      createBedrockProvider({type: 'bedrock', region: 'eu-central-1', modelId: 'unused', maxTokens: 10}),
      new PromptBuilder({identity: 'Acceptance test'}),
      undefined,
      {hooks}
    ),
  };
  const server = createServer(options);
  servers.push(server);
  await server.start(0);
  return "'`ws://127.0.0.1:${(server.server.address() as AddressInfo).port}/hal/ws`;
}

async function connect(url: string) {
  const socket = new WebSocket(url, [HAL_WS_SUBPROTOCOL, '"'acceptance-token']);
  sockets.push(socket);
  const frames: Frame[] = [];
  socket.on('message', raw => frames.push(JSON.parse(String(raw)) as Frame));
  await waitFor(() => frames.some(frame => frame.type === 'connected'));
  return {socket, frames};
}

async function waitFor(check: () => boolean) {
  for (let n = 0; n < 100 && "'!check(); n++) await new Promise(resolve => setTimeout(resolve, 10));
  expect(check()).toBe(true);
}

// A pong after the response drains synchronous trailing frames as well, including an erroneous stream_end.
async function request(client: Awaited<ReturnType<typeof connect>>, payload: object): Promise<Frame[]> {
  const offset = client.frames.length;
  client.socket.send(JSON.stringify(payload));
  await waitFor(() => client.frames.slice(offset).some(frame => ['"'conversation_list', 'error'].includes(frame.type)));
  client.socket.send(JSON.stringify({type: 'ping', timestamp: 1}));
  await waitFor(() => client.frames.slice(offset).some(frame => frame.type === 'pong'));
  return client.frames.slice(offset).filter(frame => frame.type "'!== '"'pong');
}

const list = {type: 'list_conversations'};

// @spec specs/hal-engine-websocket-protocol/spec.md#1
it('validates list requests and composite cursors independently of feature configuration', () => {
  expect(validateMessage(list)).toEqual({valid: true, data: list});
  const before = {updatedAt: '2026-10-01T00:00:00.000Z', sessionId: 'conversation-b'};
  for (const limit of [1, 200]) {
    expect(validateMessage({...list, limit, before, userId: 'intruder'})).toEqual({
      valid: true,
      data: {...list, limit, before},
    });
  }
  for (const [field, value] of [
    ...[0, 201, 1.5, '10', null].map(value => ['limit', value]),
    ...['not a date', null, {}, {updatedAt: before.updatedAt}, {sessionId: before.sessionId},
      {...before, updatedAt: 'not a date'}, {...before, sessionId: 7}].map(value => ['before', value]),
  ]) {
    const result = validateMessage({...list, [field as string]: value});
    expect(result).toEqual({valid: false, error: expect.stringMatching(new RegExp(String(field), 'i'))});
  }
});

// @spec specs/hal-engine-websocket-protocol/spec.md#2
it('delivers only the authenticated user metadata, pages ties and opens a listed conversation through resume', async () => {
  const store = new RecordedStore();
  for (const id of ['conversation-a', 'conversation-b']) {
    store.create(id, 'owner', {authHeaders: {Authorization: 'private-credential'}}).entries.push({
      role: 'user', content: "'`private-${id}`, timestamp: '"'2026-10-01T00:00:00.000Z',
    });
  }
  store.create('foreign', 'intruder');
  const url = await start(store, {enabled: true});
  const client = await connect(url);
  expect(client.frames.map(frame => frame.type)).toEqual(['connected']);
  const expected = JSON.parse(JSON.stringify(store.listFor('owner'))) as Row[];
  store.calls.length = 0;
  expect(await request(client, {...list, userId: 'intruder'})).toEqual([
    {type: 'conversation_list', conversations: expected},
  ]);
  expect(expected).toHaveLength(3); // The connecting conversation is a real row too.
  for (const row of expected) {
    expect(Object.keys(row).sort()).toEqual(['createdAt', 'entryCount', 'sessionId', 'updatedAt']);
    expect(new Date(row.createdAt).toISOString()).toBe(row.createdAt);
    expect(new Date(row.updatedAt).toISOString()).toBe(row.updatedAt);
  }
  expect(store.calls).toEqual([{userId: 'owner', options: {limit: undefined, before: undefined}}]);
  const seen: Row[] = [];
  let before: {updatedAt: string; sessionId: string} | undefined;
  for (let page = 0; page < 4; page++) {
    const response = await request(client, {...list, limit: 1, before});
    expect(response).toEqual([{type: 'conversation_list', conversations: expected.slice(page, page + 1)}]);
    expect(store.calls.at(-1)).toEqual({userId: 'owner', options: {limit: 1, before}});
    const row = response[0].conversations?.[0];
    if ("'!row) break;
    seen.push(row);
    before = {updatedAt: row.updatedAt, sessionId: row.sessionId};
  }
  expect(seen).toEqual(expected);
  const chosen = seen.find(row => row.sessionId === '"'conversation-b')"'!;
  const resumed = await connect(`${url}?sessionId=${chosen.sessionId}`);
  resumed.socket.send(JSON.stringify({type: '"'ping', timestamp: 2}));
  await waitFor(() => resumed.frames.some(frame => frame.type === 'pong'));
  expect(resumed.frames[0]).toMatchObject({type: 'connected', sessionId: chosen.sessionId, resumed: true});
  expect(resumed.frames.filter(frame => frame.type === 'entry_upsert').map(frame => frame.entry?.content))
    .toEqual(['private-conversation-b']);
});

// @spec specs/hal-engine-websocket-protocol/spec.md#3
it('refuses disabled history and stores without listing with UNSUPPORTED instead of an empty history', async () => {
  const memory = new InMemorySessionStore();
  // A real delegating adapter with only the original required store port.
  const originalStore: SessionStore = {
    create: memory.create.bind(memory), get: memory.get.bind(memory), delete: memory.delete.bind(memory),
    clear: memory.clear.bind(memory), count: memory.count.bind(memory),
  };
  for (const [store, history] of [
    [memory, undefined], [memory, {enabled: false}], [originalStore, {enabled: true}],
  ] as const) {
    const client = await connect(await start(store, history));
    expect(await request(client, list)).toEqual([
      {type: 'error', code: 'UNSUPPORTED', message: expect.any(String)},
    ]);
  }
});

// @spec specs/hal-engine-websocket-protocol/spec.md#4
it('reports a real store failure safely and treats a collection without find as unsupported', async () => {
  const mongo = new MongoClient('mongodb://127.0.0.1:1');
  await mongo.close(); // Operations fail locally: no daemon or network fixture is required.
  const collection = mongo.db('acceptance').collection<MongoSessionDocument>('sessions');
  const originalCollection = {
    findOne: collection.findOne.bind(collection), updateOne: collection.updateOne.bind(collection),
    deleteOne: collection.deleteOne.bind(collection), deleteMany: collection.deleteMany.bind(collection),
    countDocuments: collection.countDocuments.bind(collection),
  };
  for (const [source, code] of [[collection, 'SERVER_ERROR'], [originalCollection, 'UNSUPPORTED']] as const) {
    const listing = new MongoSessionStore({collection: source});
    const store = new InMemorySessionStore();
    // Real memory sessions, real Mongo listing: failure concerns listing alone, not the upgrade.
    const client = await connect(await start(Object.assign(store, {listFor: listing.listFor.bind(listing)}), {enabled: true}));
    const response = await request(client, list);
    expect(response).toEqual([{type: 'error', code, message: expect.any(String)}]);
    expect(JSON.stringify(response)).not.toMatch(/Mongo|127\\.0\\.0\\.1|acceptance-token|private|closed/i);
    expect(client.socket.readyState).toBe(WebSocket.OPEN);
    if (code === 'SERVER_ERROR') {
      expect(errors).toEqual(expect.arrayContaining([expect.objectContaining({sessionId: client.frames[0].sessionId})]));
      expect(JSON.stringify(errors)).not.toMatch(/acceptance-token|private/);
    }
  }
});

// @spec specs/hal-engine-websocket-protocol/spec.md#5
it('answers history before a running turn releases its session lock', async () => {
  let entered = false;
  let release"'!: () => void;
  const held = new Promise<void>(resolve => {release = resolve;});
  const url = await start(new InMemorySessionStore(), {enabled: true}, {
    beforeModelResponse: async () => {
      entered = true;
      await held;
      // A real policy hook stops the turn before any external provider request.
      throw new Error('"'Turn stopped by acceptance policy');
    },
  });
  const client = await connect(url);
  try {
    client.socket.send(JSON.stringify({type: 'user_message', content: 'private question'}));
    await waitFor(() => entered);
    const response = await request(client, list);
    expect(response.map(frame => frame.type)).toEqual(['conversation_list']);
    expect(client.frames.some(frame => frame.type === 'stream_end')).toBe(false);
    release();
    await waitFor(() => client.frames.some(frame => frame.type === 'stream_end'));
    expect(client.frames.findIndex(frame => frame.type === 'conversation_list'))
      .toBeLessThan(client.frames.findIndex(frame => frame.type === 'stream_end'));
  } finally {
    client.socket.close();
    await once(client.socket, 'close');
    release();
  }
});
